param([ValidateSet('build','test','capture')][string]$Action='build')
$ErrorActionPreference='Stop';$ProgressPreference='SilentlyContinue';[Console]::OutputEncoding=[Text.UTF8Encoding]::new($false)
if(-not [Environment]::MachineName.Equals('baiying',[StringComparison]::OrdinalIgnoreCase)){throw 'Requires baiying'}
$repo='D:\projects\AIMA-public-wmma-scalar-carry-envelope-20260914-r2';$seed='D:\projects\AIMA-public-wmma-scalar-carry-envelope-20260914'
$sha='d7ed15dfed474e5620ab3b15218c54025d927b0b';$bundle='D:\projects\wmma-scalar-carry-envelope-d7ed15d.bundle'
if((Get-FileHash $bundle -Algorithm SHA256).Hash.ToLowerInvariant() -ne '4a595527dfb69d88987344e51a33737326c74af28030411cb23c0cf436d0e299'){throw 'Bundle changed'}
if(-not (Test-Path $repo)){
 & git -C $seed fetch $bundle HEAD;if($LASTEXITCODE -ne 0){throw 'Fetch failed'}
 & git -C $seed worktree add --detach $repo $sha;if($LASTEXITCODE -ne 0){throw 'Worktree creation failed'}
}
if((& git -C $repo rev-parse HEAD).Trim() -ne $sha -or @(& git -C $repo status --porcelain).Count -ne 0){throw 'Source mismatch'}
$build=Join-Path $repo 'build\wmma-scalar-carry-envelope-r2';$null=New-Item -ItemType Directory -Path $build -Force
$source=Join-Path $repo 'tests\native\wmma_projection_envelope_probe.cpp';$exe=Join-Path $build 'wmma-scalar-carry-envelope.exe'
$sourceInputs=@();foreach($name in @(& git -C $repo ls-files 'native/providers/moe_accumulator/*.h' 'native/providers/ck_fmha/*.h' 'tests/native/wmma_projection_envelope_probe.cpp' 'scripts/baiying_guarded_inference.ps1' 'tests/powershell/test_guarded_inference_arguments.ps1')){$sourceInputs+=@{file=$name;sha256=(Get-FileHash (Join-Path $repo $name) -Algorithm SHA256).Hash.ToLowerInvariant()}}
$spec=[ordered]@{executable='';arguments=@();working_directory=$repo;repo_commit=$sha;command_file=$PSCommandPath;command_file_sha256=(Get-FileHash $PSCommandPath -Algorithm SHA256).Hash.ToLowerInvariant();source_inputs=$sourceInputs;model='none; compare fused WMMA,zero-C with scalar nearest-even,and zero-C with scalar toward-zero carry. All envelopes are diagnostic; smaller bounds are hypotheses only';model_loaded=$false;inference_acceptance=$false;performance_acceptance=$false;product_dispatch_changed=$false}
$env:PATH='C:\Program Files\AMD\ROCm\7.1\bin;'+$env:PATH
if($Action -eq 'build'){
 $spec.executable='C:\Program Files\AMD\ROCm\7.1\bin\hipcc.exe'
 $spec.arguments=@('-std=c++17','-O3','-Rpass-analysis=kernel-resource-usage','-DQRT_SM121_DPP_REDUCTION=1','-DQRT_SM121_COMPACT_NORMALIZE=1','--offload-arch=gfx1151',$source,'-o',$exe);$timeout=120
}else{
 $metaPath=Join-Path $build 'build-provenance.json';$meta=[IO.File]::ReadAllText($metaPath)|ConvertFrom-Json
 if($meta.repo_commit -ne $sha -or (Get-FileHash $exe -Algorithm SHA256).Hash.ToLowerInvariant() -ne $meta.executable.sha256){throw 'Executable provenance mismatch'}
 $spec.build_provenance_sha256=(Get-FileHash $metaPath -Algorithm SHA256).Hash.ToLowerInvariant()
 $spec.executable=$exe;$timeout=120;$spec.arguments=@('--selftest')
 if($Action -eq 'capture'){
  $inputTensor='D:\projects\AIMA-public-exact-ab-20260910\build\fla-model-q7169-embeddingnorm-capture-r1\input-rmsnorm-bf16.bin'
  $weightTensor='D:\projects\AIMA-public-capture-20260910\build\layer0-weights-r1\qkv.bin'
  $referenceTensor='D:\projects\sm121-qkv-reference-9510d980.bin'
  $tensors=@(@{path=$inputTensor;sha256='6c67321f81040780088a742070c48ab3023043b8ef9de71d1ed5a970a8fe9161'},@{path=$weightTensor;sha256='b06edcc9973be74f862d072f89a195e2eecea067ee615144be8510656122401f'},@{path=$referenceTensor;sha256='9510d98057e047e7dd6f4e7b9b6010862e54e938d37bb854078c2de419f0bf37'})
  foreach($tensor in $tensors){if((Get-FileHash $tensor.path -Algorithm SHA256).Hash.ToLowerInvariant() -ne $tensor.sha256){throw 'Original QKV tensor changed'}}
  $spec.arguments=@('--real-qkv',$inputTensor,$weightTensor,$referenceTensor);$spec.tensor_inputs=$tensors
  $spec.model='D:\models\Qwen3.6-35B-A3B; deterministic16384 sampled original layer-zero QKV dots'
  $spec.model_index_sha256='41b9356101ebf8e7519e150dc811f80c4226e727301fbb032b890f006ed0be83'
  $spec.gb10_reference_host='aitopatom-66c4';$spec.gb10_capture_sha256='5522ec3e4725adf459e505dff61aa3981a08b416b7b2bfe40e929ccf250b4d8b'
  $spec.prompt_sha256='26515be92b5563d921bade3ed6673ffe9e0c6560fbd7d78f587a0400da802804'
  $spec.reference_is_compute_input=$false;$spec.full_tensor_comparison=$false
 }
}
$specPath=Join-Path $build ($Action+'-spec-r2.json');$out=Join-Path $repo ('build\wmma-scalar-carry-envelope-'+$Action+'-r2')
if((Test-Path $specPath) -or (Test-Path $out)){throw 'Evidence exists'}
[IO.File]::WriteAllText($specPath,($spec|ConvertTo-Json -Depth 8),[Text.UTF8Encoding]::new($false))
& (Join-Path $repo 'scripts\baiying_guarded_inference.ps1') -SpecPath $specPath -OutDir $out -TimeoutSeconds $timeout|Out-Null
$r=[IO.File]::ReadAllText((Join-Path $out 'run-record.json'))|ConvertFrom-Json
$r|Select-Object reason,exit_code,wall_ms,host_checks|ConvertTo-Json -Depth 5
foreach($name in @('product.stdout.jsonl','product.stderr.log')){Get-Content (Join-Path $out $name) -Tail 12|ForEach-Object {$_.Substring(0,[Math]::Min(700,$_.Length))}}
if($r.reason -ne 'completed' -or $r.exit_code -ne 0 -or -not $r.host_checks_pass){throw 'Native core action failed'}
if($Action -eq 'build'){
 $meta=[ordered]@{host=[Environment]::MachineName;repo_commit=$sha;source_inputs=$sourceInputs;command_file=$PSCommandPath;command_file_sha256=$spec.command_file_sha256;compiler=$spec.executable;arguments=$spec.arguments;run_record_sha256=(Get-FileHash (Join-Path $out 'run-record.json') -Algorithm SHA256).Hash.ToLowerInvariant();executable=@{file=$exe;bytes=(Get-Item $exe).Length;sha256=(Get-FileHash $exe -Algorithm SHA256).Hash.ToLowerInvariant()}}
 [IO.File]::WriteAllText((Join-Path $build 'build-provenance.json'),($meta|ConvertTo-Json -Depth 8),[Text.UTF8Encoding]::new($false))
}else{
 $reports=@([IO.File]::ReadAllLines((Join-Path $out 'product.stdout.jsonl'))|Where-Object {$_.StartsWith('{')}|ForEach-Object {$_|ConvertFrom-Json})
 $expected=if($Action -eq 'capture'){12}else{72}
 if($reports.Count -ne $expected){throw 'Missing projection envelope cases'}
 foreach($report in $reports){
  if(-not $report.redzones_pass -or -not $report.immutable_inputs -or $report.nonfinite -ne 0 -or $report.external_reference_differences -ne 0){throw 'Memory,finite or external reference failure'}
  if($report.envelope -eq 0 -and ($report.prefix_undercoverage -ne 0 -or $report.false_bf16_admissions -ne 0)){throw 'Established envelope failed'}
 }
}

